/**
 * The one way the app reads the archive.
 *
 * `work-data.ts` is generated by `scripts/harvest.mjs` and gets overwritten;
 * this file is hand-written and stable, so every page imports from here. It
 * also holds the editorial decisions the raw data cannot make — what is
 * featured, what leads the homepage, and how the old site's three nav groups
 * collapse into the new two.
 */
import { PROJECTS, CATEGORIES } from "./work-data";
import type { Project, Category, Frame } from "./work-types";

export type { Project, Category, Frame };
export { PROJECTS, CATEGORIES };

/**
 * The old nav split commissioned work across WORK and MUSIC, which asked a
 * visitor to know in advance whether a cover-art job files under "music" or
 * "work". Both are commissions, judged by the same people, so they merge.
 *
 * SESSIONS stays separate — a graduation client and an art director want
 * different things from the first screen (price and dates vs. clients and
 * credits), and that is the one split worth keeping.
 */
const inSessions = (p: Project) => p.categories.some((c) => c.section === "SESSIONS");

/** Commissioned work: editorial, campaigns, portraits, music, film. */
export const COMMISSIONS: Project[] = PROJECTS.filter(
  (p) => p.categories.length > 0 && !inSessions(p),
);

/** Client-session work: graduation, headshots, weddings, studio digitals. */
export const SESSIONS: Project[] = PROJECTS.filter(inSessions);

/**
 * Projects the old site published but never linked from its nav — older work,
 * tests, one-offs. They keep working as routes so nothing already linked or
 * indexed breaks, but they stay out of the indexes until Julian files one
 * under a category by hand.
 */
export const UNFILED: Project[] = PROJECTS.filter((p) => p.categories.length === 0);

export const WORK_CATEGORIES: Category[] = CATEGORIES.filter((c) => c.section !== "SESSIONS");
export const SESSION_CATEGORIES: Category[] = CATEGORIES.filter((c) => c.section === "SESSIONS");

const bySlug = new Map(PROJECTS.map((p) => [p.slug, p]));

export const getProject = (slug: string): Project | undefined => bySlug.get(slug);

export const projectsIn = (categorySlug: string): Project[] =>
  PROJECTS.filter((p) => p.categories.some((c) => c.slug === categorySlug));

/**
 * The frame a project is represented by elsewhere on the site — the small
 * derivative of its opening image.
 *
 * The opener, because Julian already sequences his galleries and the first
 * frame is a deliberate choice; second-guessing it with "the widest" or "the
 * darkest" would override an edit he already made.
 */
export const coverOf = (p: Project): Frame => p.cover;

/**
 * Homepage order. Named explicitly rather than derived, because "what leads"
 * is the most editorial decision on the site and it should be one obvious
 * line to change.
 *
 * WIRED first: it is the strongest credential, and the thing a new visitor
 * should see before anything else.
 */
export const FEATURED_SLUGS = [
  "wired-magazine",
  "oakley-x-nike",
  "luxe-meets-future",
  "dystopia",
  "ukiyosunknown",
  "sago",
] as const;

export const FEATURED: Project[] = FEATURED_SLUGS.map((s) => bySlug.get(s)).filter(
  (p): p is Project => Boolean(p),
);

/**
 * The press strip on the homepage. The old site buried these as plain text at
 * the bottom of /about; they are the reason an art director keeps reading, so
 * they move up and each links into the work it refers to.
 */
export const PRESS = [
  { name: "WIRED", slug: "wired-magazine" },
  { name: "Oakley x Nike", slug: "oakley-x-nike" },
  { name: "UKIYOSUNKNOWN", slug: "ukiyosunknown" },
  { name: "JUBO", slug: "jubo" },
  { name: "SAGO", slug: "sago" },
].filter((p) => bySlug.has(p.slug));

/**
 * The homepage cover.
 *
 * One frame, static. A single photograph is the oldest and least dateable way
 * to open a portfolio, and it is the fastest — one image to decode, which is
 * what a visitor's patience is actually spent on.
 *
 * Named here rather than derived, because this is the most consequential
 * editorial decision on the site: it is the first thing anyone sees. Change
 * the slug to change the cover.
 *
 * The full-size frame, not the small cover derivative — this one runs the
 * full height of the page on a large display.
 */
export const COVER_SLUG = "wired-magazine";

export const HERO: { project: Project; frame: Frame } | null = (() => {
  const project = bySlug.get(COVER_SLUG) ?? FEATURED[0] ?? COMMISSIONS[0];
  // Prefer a portrait frame. The cover sits in a half-width, full-height
  // column, and `object-cover` on a landscape frame in that shape crops away
  // both sides — usually most of the subject.
  const frame = project?.images.find((f) => f.height > f.width) ?? project?.images[0];
  return project && frame ? { project, frame } : null;
})();

/**
 * Which contact-form branch a project should pre-select.
 *
 * The point is that someone who has just looked at a campaign and wants one
 * arrives at the form with "Campaign" already chosen and the usage-rights
 * question already asked. Every question they do not have to answer from a
 * cold start is a chance they do not abandon the form.
 */
export const enquiryTypeFor = (p: Project): string => {
  const slugs = p.categories.map((c) => c.slug);

  if (slugs.some((s) => ["artist-presskit", "music-video", "coverart", "events"].includes(s)))
    return "music";
  if (slugs.includes("campaigns")) return "campaign";
  if (slugs.includes("editorial")) return "editorial";
  if (p.categories.some((c) => c.section === "SESSIONS")) return "session";
  return "other";
};

/**
 * The project after this one, for the end of a case study.
 *
 * A project page that ends in a footer is a dead end, and a dead end is an
 * exit. Wrapping round at the end means there is always a next thing.
 */
export const nextAfter = (p: Project): Project | undefined => {
  const pool = p.categories.some((c) => c.section === "SESSIONS") ? SESSIONS : COMMISSIONS;
  const i = pool.findIndex((x) => x.slug === p.slug);
  if (i === -1) return pool[0];
  return pool[(i + 1) % pool.length];
};

/**
 * The disciplines the homepage cycles through, each with a frame to show for
 * it.
 *
 * This is what the cover is *for*: "photographer" is a job title, whereas
 * editorial, campaigns, portraits and music are the four things somebody
 * might actually be here to commission. Switching between them says the range
 * in the first few seconds, which one static cover cannot.
 *
 * Built from the nav's own category order rather than a hand-written list, so
 * it cannot drift out of step with the work. Each one takes its frame from the
 * first project filed under it — Julian's own ordering, so the lead project is
 * already his pick — preferring a portrait frame, because the cover sits in a
 * tall column and `object-cover` on a landscape frame there crops away both
 * sides.
 */
export type Discipline = {
  slug: string;
  name: string;
  /** How many projects are filed under it, for the index. */
  count: number;
  project: Project;
  frame: Frame;
};

/**
 * Hand-picked cover frames, overriding the one derived from the archive.
 *
 * These live in `public/hero/` rather than in `public/work/`, because they are
 * chosen to be a cover — a specific frame Julian wants leading the site —
 * rather than being part of a project's sequence. That also keeps them clear
 * of `scripts/harvest.mjs`, which owns everything under `public/work/`.
 *
 * `color` is the mat drawn behind the picture where the column is wider or
 * taller than the frame. It is the image's mean, not its dominant: on a
 * sunset frame the dominant bucket comes back near-black, which reads as a
 * letterbox bar instead of a mount.
 *
 * Add a full-resolution original to `PICS/`, then process it the same way the
 * archive is processed — 1600px wide, mozjpeg q82 — and add an entry here.
 */
const COVER_OVERRIDES: Record<string, Frame> = {
  portraits: {
    src: "/hero/cover.jpg",
    width: 1600,
    height: 2133,
    color: "#897A74",
    alt: "Model in a fur-trimmed hooded coat on the shoreline at sunset",
  },
};

export const DISCIPLINES: Discipline[] = WORK_CATEGORIES.slice(0, 4)
  .map((category) => {
    const inCategory = projectsIn(category.slug);
    const project = inCategory[0];
    if (!project) return null;

    const frame =
      COVER_OVERRIDES[category.slug] ??
      project.images.find((f) => f.height > f.width) ??
      project.images[0];
    if (!frame) return null;

    return { slug: category.slug, name: category.name, count: inCategory.length, project, frame };
  })
  .filter((d): d is Discipline => d !== null);
